**packages/components/src/renderers/complex/data-table.tsx:209**
* There are existing tests for DataTable editing, but the newly added behaviors (`singleClickEdit` click-to-edit, `selectionStyle: 'hover'`, ghost rows when empty, and auto column width fallback) aren't covered. Adding a few focused RTL/Vitest tests would help prevent regressions for these UX-critical features.
```
    editable = false,
    singleClickEdit = false,
    selectionStyle = 'always',
    rowClassName,
    rowStyle,
    className,
    frozenColumns = 0,
    showRowNumbers = false,
    showAddRow = false,
  } = schema;

  // i18n support for pagination labels
  const { t } = useTableTranslation();

  // Ensure data is always an array – provider config objects or null/undefined
  // must not reach array operations like .filter() / .some()
  const data = Array.isArray(rawData) ? rawData : [];

  // Normalize columns to support legacy keys (label/name) from existing JSONs
  const initialColumns = useMemo(() => {
    return rawColumns.map((col: any) => ({
      ...col,
      header: col.header || col.label,
      accessorKey: col.accessorKey || col.name
    }));
  }, [rawColumns]);

  // Auto-size columns: estimate width from header and data content for columns without explicit widths
  const autoSizedWidths = useMemo(() => {
    const widths: Record<string, number> = {};
    const cols = rawColumns.map((col: any) => ({
      header: col.header || col.label,
      accessorKey: col.accessorKey || col.name,
      width: col.width,
    }));
    for (const col of cols) {
      if (col.width) continue; // Skip columns with explicit widths
      const headerLen = (col.header || '').length;
      let maxLen = headerLen;
      // Sample up to 50 rows for content width estimation
      const sampleRows = data.slice(0, 50);
      for (const row of sampleRows) {
        const val = row[col.accessorKey];
        const len = val != null ? String(val).length : 0;
        if (len > maxLen) maxLen = len;
      }
      // Estimate pixel width: ~8px per character + 48px padding, min 80, max 400
      widths[col.accessorKey] = Math.min(400, Math.max(80, maxLen * 8 + 48));
    }
    return widths;
  }, [rawColumns, data]);
```
**packages/components/src/renderers/complex/data-table.tsx:872**
* In `selectionStyle === 'hover'` mode the checkbox is hidden via `opacity: 0`, but it remains focusable/clickable (tab navigation can land on an invisible control). Consider using `invisible`/`pointer-events-none` (and/or managing `tabIndex`/`aria-hidden`) when not hovered and not selected to keep keyboard/a11y behavior consistent.
```
                        <TableCell className={cn(frozenColumns > 0 && "sticky left-0 z-10 bg-background", selectionStyle === 'hover' && "relative")}>
